DO $$ BEGIN
 ASSERT current_database() != 'yongxiang_plumb', 'production forbidden';
 ASSERT current_database() = 'yongxiang_plumb_r39_clone', 'clone only';
END $$;
SELECT pg_advisory_xact_lock(hashtext('r48_migration'));
CREATE TABLE IF NOT EXISTS public.r48_config (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 case_identity text NOT NULL DEFAULT 'full' CHECK(case_identity IN ('full','base_sub')),
 min_n int NOT NULL DEFAULT 10 CHECK(min_n>0));
INSERT INTO public.r48_config DEFAULT VALUES ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.r48_normalize_code(v text) RETURNS text
 LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
 SELECT regexp_replace(regexp_replace(upper(normalize(coalesce(v,''),NFKC)), '[[:space:]​‌‍﻿]', '', 'g'),
 '^([A-Z][0-9]{6})([0-9]{2}[A-Z]?)$', '\1-\2') $$;
CREATE OR REPLACE FUNCTION public.r48_case_key(v text) RETURNS text LANGUAGE sql STABLE AS $$
 SELECT CASE WHEN (SELECT case_identity FROM public.r48_config)='base_sub' AND position('-' in public.r48_normalize_code(v))>0
 THEN regexp_replace(public.r48_normalize_code(v),'([0-9])[A-Z]$','\1') ELSE public.r48_normalize_code(v) END $$;
CREATE OR REPLACE FUNCTION public.r48_filled_fields(v jsonb) RETURNS int LANGUAGE sql IMMUTABLE AS $$
 SELECT count(*)::int FROM jsonb_each(v) WHERE value <> 'null'::jsonb AND value <> '""'::jsonb $$;
ALTER TABLE public."case" ADD COLUMN IF NOT EXISTS merged_into uuid REFERENCES public."case"(id);
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS lark_record_id text;
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS engineering_code_raw text;
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS engineering_code_norm text;
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS version_tag text;
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS amount numeric;
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS created_by text;
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS modified_at timestamptz;
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS payload jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS customer_name text;
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS source_quote_date text;
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS v4_referenced boolean NOT NULL DEFAULT false;
ALTER TABLE public.quote ADD COLUMN IF NOT EXISTS filled_fields int GENERATED ALWAYS AS (public.r48_filled_fields(payload)) STORED;
CREATE TABLE IF NOT EXISTS public.r48_quote_original AS SELECT id,quote_no,case_id,source_record_id FROM public.quote;
INSERT INTO public.r48_quote_original SELECT q.id,q.quote_no,q.case_id,q.source_record_id FROM public.quote q WHERE NOT EXISTS(SELECT 1 FROM public.r48_quote_original o WHERE o.id=q.id);
CREATE TABLE IF NOT EXISTS public.r48_quote_source(record_id text PRIMARY KEY,record jsonb NOT NULL);
UPDATE public.r48_config SET case_identity='full';
