$r48source$::jsonb) r ON CONFLICT(record_id) DO UPDATE SET record=excluded.record;
-- Existing quote_no uniqueness confused source records with quote versions. Preserve IDs and all child rows.
ALTER TABLE public.quote DROP CONSTRAINT IF EXISTS quote_quote_no_key;
-- One native source identity is retained per row; older mirror rows get stable legacy identities.
WITH ranked AS (SELECT id,source_record_id,row_number() OVER(PARTITION BY source_record_id ORDER BY (source_base_token IS NOT NULL) DESC,id) rn FROM public.quote)
UPDATE public.quote q SET lark_record_id=CASE WHEN r.source_record_id IS NOT NULL AND r.rn=1 THEN r.source_record_id ELSE 'legacy:'||q.id END
FROM ranked r WHERE r.id=q.id AND q.lark_record_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS quote_lark_record_id_uq ON public.quote(lark_record_id);
ALTER TABLE public.quote ALTER COLUMN lark_record_id SET NOT NULL;
INSERT INTO public.quote(org_id,quote_no,lark_record_id,source_record_id,source_base_token)
SELECT 'YX',coalesce(nullif(record->'fields'->>'報價編號',''),'SOURCE:'||record_id),record_id,record_id,record->>'base_token'
FROM public.r48_quote_source s WHERE NOT EXISTS(SELECT 1 FROM public.quote q WHERE q.lark_record_id=s.record_id);
UPDATE public.quote q SET
 quote_no=coalesce(nullif(public.r48_normalize_code(s.record->'fields'->>'報價編號'),''),'SOURCE:'||s.record_id),
 engineering_code_raw=coalesce(s.record->'fields'->>'工程編號',''),
 engineering_code_norm=public.r48_normalize_code(s.record->'fields'->>'工程編號'),
 version_tag=substring(public.r48_normalize_code(s.record->'fields'->>'報價編號') from '([A-Z]+)$'),
 amount=nullif(replace(s.record->'fields'->>'契約價格(未稅)',',',''),'')::numeric,
 customer_name=coalesce(btrim(s.record->'fields'->>'行號單位'),''),
 source_quote_date=coalesce(btrim(s.record->'fields'->>'報價日期'),''),
 created_by=coalesce(s.record->'fields'->'填寫人'->0->>'name',''),
 modified_at=nullif(coalesce(s.record->>'modified_at',s.record->'fields'->>'最後修改時間',s.record->'fields'->>'修改時間'),'')::timestamptz,
 payload=s.record->'fields',v4_referenced=coalesce((s.record->>'confirmed')::boolean,false)
FROM public.r48_quote_source s WHERE q.lark_record_id=s.record_id;
UPDATE public.quote q SET engineering_code_raw=coalesce(q.engineering_code_raw,q.raw_case_code,k.raw_case_code,k.case_code,''),
 engineering_code_norm=public.r48_normalize_code(coalesce(q.engineering_code_raw,q.raw_case_code,k.raw_case_code,k.case_code,'')),
 amount=coalesce(q.amount,q.quoted_total),customer_name=coalesce(q.customer_name,k.client,''),
 source_quote_date=coalesce(q.source_quote_date,q.quote_date::text,''),
 version_tag=coalesce(q.version_tag,substring(q.quote_no from '([A-Z]+)$'))
FROM public."case" k WHERE k.id=q.case_id AND q.lark_record_id LIKE 'legacy:%';
CREATE TABLE IF NOT EXISTS public.quote_case_link (
 quote_id uuid PRIMARY KEY REFERENCES public.quote(id), case_id uuid NOT NULL REFERENCES public."case"(id),
 link_role text NOT NULL CHECK(link_role IN ('canonical','revision','duplicate','pending_human')),
 duplicate_of uuid REFERENCES public.quote(id), decided_by text NOT NULL DEFAULT 'rule:canonical_quote_rule_v1',
 decided_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS qcl_one_canonical_per_case ON public.quote_case_link(case_id) WHERE link_role='canonical';
-- Case map preserves legacy/placeholder codes without guessing an invalid formal case_code.
CREATE TABLE IF NOT EXISTS public.r48_case_identity_map(identity_mode text NOT NULL,code text NOT NULL,case_id uuid NOT NULL REFERENCES public."case"(id),PRIMARY KEY(identity_mode,code));
DO $$ DECLARE r record; target uuid; mode text; BEGIN
 SELECT case_identity INTO mode FROM public.r48_config;
 FOR r IN SELECT DISTINCT coalesce(nullif(public.r48_case_key(q.engineering_code_raw),''),nullif(q.quote_no,''),'SOURCE:'||q.lark_record_id) code
 FROM public.quote q JOIN public.r48_quote_source s ON s.record_id=q.lark_record_id LOOP
  SELECT m.case_id INTO target FROM public.r48_case_identity_map m WHERE m.identity_mode=mode AND m.code=r.code;
  IF target IS NULL THEN
   SELECT k.id INTO target FROM public."case" k WHERE k.org_id='YX' AND k.merged_into IS NULL AND k.case_code=r.code ORDER BY k.id LIMIT 1;
   IF target IS NULL THEN
    INSERT INTO public."case"(org_id,case_code,raw_case_code,title,status)
    VALUES('YX',CASE WHEN r.code ~ '^[A-MVXZ][0-9]{6}(-[0-9A-Z]{1,3})?$' THEN r.code END,r.code,r.code,'preliminary') RETURNING id INTO target;
   END IF;
   INSERT INTO public.r48_case_identity_map VALUES(mode,r.code,target);
  END IF;
 END LOOP;
END $$;
INSERT INTO public.quote_case_link(quote_id,case_id,link_role)
SELECT q.id,m.case_id,'pending_human' FROM public.quote q
JOIN public.r48_quote_source s ON s.record_id=q.lark_record_id
JOIN public.r48_case_identity_map m ON m.identity_mode=(SELECT case_identity FROM public.r48_config)
 AND m.code=coalesce(nullif(public.r48_case_key(q.engineering_code_raw),''),nullif(q.quote_no,''),'SOURCE:'||q.lark_record_id)
ON CONFLICT(quote_id) DO UPDATE SET case_id=excluded.case_id,link_role='pending_human',duplicate_of=NULL;
-- Earlier imports created synthetic numbered mirrors. Preserve the quote rows and
-- original case references, but do not count a mirror as an additional native quotation.
DELETE FROM public.quote_case_link l USING public.quote q WHERE l.quote_id=q.id
 AND coalesce(l.decided_by,'') <> 'r49:legacy-link-backfill'
 AND coalesce(l.decided_by,'') <> 'r50:missing-legacy-link-backfill'
 AND NOT EXISTS(SELECT 1 FROM public.r48_quote_source own_src WHERE own_src.record_id=q.lark_record_id)
 AND EXISTS(SELECT 1 FROM public.quote_case_link real_link JOIN public.quote real_q ON real_q.id=real_link.quote_id JOIN public.r48_quote_source src ON src.record_id=real_q.lark_record_id WHERE real_link.case_id=l.case_id);
INSERT INTO public.quote_case_link(quote_id,case_id,link_role)
SELECT q.id,coalesce(k.merged_into,k.id),'pending_human' FROM public.quote q JOIN public."case" k ON k.id=q.case_id
WHERE NOT EXISTS(SELECT 1 FROM public.quote_case_link l WHERE l.quote_id=q.id)
 AND NOT EXISTS(SELECT 1 FROM public.quote_case_link rl JOIN public.quote rq ON rq.id=rl.quote_id JOIN public.r48_quote_source src ON src.record_id=rq.lark_record_id WHERE rl.case_id=coalesce(k.merged_into,k.id))
ON CONFLICT DO NOTHING;
-- Relink source rows to their grouped case. No quotation or case history is deleted.
UPDATE public.quote q SET case_id=l.case_id FROM public.quote_case_link l WHERE l.quote_id=q.id AND q.case_id IS DISTINCT FROM l.case_id;
UPDATE public."case" c SET merged_into=k.id FROM public."case" k
WHERE c.case_code IS NULL AND k.org_id=c.org_id AND k.case_code=public.r48_normalize_code(c.raw_case_code)
 AND c.id<>k.id AND c.merged_into IS NULL;
CREATE OR REPLACE FUNCTION public.apply_canonical_quote_rule(p_case uuid) RETURNS text LANGUAGE plpgsql AS $$
DECLARE canon uuid; qn text; conflict boolean; v4_count int; BEGIN
 ASSERT current_database() != 'yongxiang_plumb'; ASSERT current_database()='yongxiang_plumb_r39_clone';
 PERFORM 1 FROM public."case" WHERE id=p_case FOR UPDATE;
 SELECT count(DISTINCT q.quote_no) INTO v4_count FROM public.quote q JOIN public.quote_case_link l ON l.quote_id=q.id
 WHERE l.case_id=p_case AND q.v4_referenced AND coalesce(l.decided_by,'') NOT IN ('r49:legacy-link-backfill','r50:missing-legacy-link-backfill');
 SELECT EXISTS(SELECT 1 FROM public.quote a JOIN public.quote_case_link la ON la.quote_id=a.id
 JOIN public.quote b ON b.quote_no=a.quote_no AND b.id<>a.id JOIN public.quote_case_link lb ON lb.quote_id=b.id
 WHERE la.case_id=p_case AND lb.case_id=p_case
 AND coalesce(la.decided_by,'') NOT IN ('r49:legacy-link-backfill','r50:missing-legacy-link-backfill')
 AND coalesce(lb.decided_by,'') NOT IN ('r49:legacy-link-backfill','r50:missing-legacy-link-backfill')
 AND (a.amount IS DISTINCT FROM b.amount OR a.customer_id IS DISTINCT FROM b.customer_id OR a.customer_name IS DISTINCT FROM b.customer_name OR a.source_quote_date IS DISTINCT FROM b.source_quote_date)) INTO conflict;
 -- Clear canonical first so the partial unique index cannot fail midway through a winner change.
 UPDATE public.quote_case_link SET link_role='pending_human',duplicate_of=NULL WHERE case_id=p_case AND coalesce(decided_by,'') NOT IN ('r49:legacy-link-backfill','r50:missing-legacy-link-backfill');
 UPDATE public.quote_case_link SET link_role='duplicate',duplicate_of=NULL WHERE case_id=p_case AND coalesce(decided_by,'') IN ('r49:legacy-link-backfill','r50:missing-legacy-link-backfill');
 IF v4_count>1 OR (v4_count=0 AND conflict) THEN RETURN 'pending_human'; END IF;
 SELECT q.id,q.quote_no INTO canon,qn FROM public.quote q JOIN public.quote_case_link l ON l.quote_id=q.id
 WHERE l.case_id=p_case AND (v4_count=0 OR q.v4_referenced)
 AND coalesce(l.decided_by,'') NOT IN ('r49:legacy-link-backfill','r50:missing-legacy-link-backfill')
 ORDER BY coalesce(q.version_tag,'') COLLATE "C" DESC,q.filled_fields DESC,q.modified_at DESC NULLS LAST,q.lark_record_id COLLATE "C" ASC LIMIT 1;
 IF canon IS NULL THEN RETURN 'empty'; END IF;
 UPDATE public.quote_case_link l SET link_role=CASE WHEN l.quote_id=canon THEN 'canonical' WHEN q.quote_no=qn THEN 'duplicate' ELSE 'revision' END,
 duplicate_of=CASE WHEN l.quote_id<>canon AND q.quote_no=qn THEN canon END,decided_at=now()
 FROM public.quote q WHERE q.id=l.quote_id AND l.case_id=p_case AND coalesce(l.decided_by,'') NOT IN ('r49:legacy-link-backfill','r50:missing-legacy-link-backfill');
 RETURN 'canonical';
END $$;
DELETE FROM public.quote_case_link l USING public.quote q
WHERE l.quote_id=q.id
  AND coalesce(l.decided_by,'') <> 'r49:legacy-link-backfill'
  AND coalesce(l.decided_by,'') <> 'r50:missing-legacy-link-backfill'
  AND NOT EXISTS(SELECT 1 FROM public.r48_quote_source own_src WHERE own_src.record_id=q.lark_record_id)
  AND EXISTS(SELECT 1 FROM public.quote_case_link real_link JOIN public.quote real_q ON real_q.id=real_link.quote_id JOIN public.r48_quote_source src ON src.record_id=real_q.lark_record_id WHERE real_link.case_id=l.case_id AND src.record ? 'cohort_group');
SELECT public.apply_canonical_quote_rule(case_id) FROM (SELECT DISTINCT case_id FROM public.quote_case_link) c;
CREATE OR REPLACE VIEW public.case_quote_summary_v AS
SELECT k.id case_id,coalesce(m.code,k.case_code,k.raw_case_code) case_code,
 max(q.quote_no) FILTER(WHERE l.link_role='canonical') canonical_quote_no,
 max(q.amount) FILTER(WHERE l.link_role='canonical') canonical_amount,
 count(*) quote_rows,count(*) FILTER(WHERE l.link_role='duplicate') duplicate_rows,
 NOT bool_or(q.v4_referenced) AND k.source_v4_id IS NULL no_v4,
 bool_or(l.link_role='pending_human') needs_human,
 bool_or(s.record ? 'cohort_group') duplicate_cohort,
 jsonb_agg(jsonb_build_object('record_id',q.lark_record_id,'quote_no',q.quote_no,'role',l.link_role,'amount',q.amount) ORDER BY q.lark_record_id COLLATE "C") quotes
FROM public."case" k JOIN public.quote_case_link l ON l.case_id=k.id JOIN public.quote q ON q.id=l.quote_id
LEFT JOIN public.r48_quote_source s ON s.record_id=q.lark_record_id
LEFT JOIN public.r48_case_identity_map m ON m.case_id=k.id AND m.identity_mode=(SELECT case_identity FROM public.r48_config)
WHERE k.merged_into IS NULL
  AND coalesce(l.decided_by,'') NOT IN ('r49:legacy-link-backfill','r50:missing-legacy-link-backfill')
GROUP BY k.id,m.code;
CREATE OR REPLACE VIEW public.r48_duplicate_breakdown_v AS
SELECT s.record->>'cohort_group' group_id,coalesce(nullif(public.r48_case_key(q.engineering_code_raw),''),q.quote_no) case_code,
 count(*) rows,count(DISTINCT coalesce(q.amount::text,'<NULL>'))>1 amount_conflict,
 count(DISTINCT coalesce(q.customer_name,'<NULL>'))>1 customer_conflict,
 count(DISTINCT coalesce(q.source_quote_date,'<NULL>'))>1 date_conflict,
 jsonb_agg(DISTINCT q.amount) amounts,jsonb_agg(DISTINCT q.customer_name) customers
FROM public.r48_quote_source s JOIN public.quote q ON q.lark_record_id=s.record_id
WHERE s.record ? 'cohort_group' GROUP BY 1,2;
CREATE OR REPLACE FUNCTION public.wilson_lb(k int,n int,z numeric DEFAULT 1.96) RETURNS numeric LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
 IF n<0 OR k<0 OR k>n OR z<=0 THEN RAISE EXCEPTION 'invalid Wilson inputs'; END IF;
 RETURN CASE WHEN n=0 THEN NULL ELSE round(((k::numeric/n)+z*z/(2*n)-z*sqrt(((k::numeric/n)*(1-k::numeric/n)+z*z/(4*n))/n))/(1+z*z/n),4) END;
END $$;
CREATE TABLE IF NOT EXISTS public.category_automation(category text PRIMARY KEY,level text NOT NULL CHECK(level IN ('auto','auto_with_flag','human_classify')),run_id uuid,set_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION public.r48_stratum_result(tp int,fp int,fn int,n int,zero_tolerance boolean DEFAULT false,min_n int DEFAULT 10,min_p numeric DEFAULT .90,min_r numeric DEFAULT .85)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE outcome text; lev text; p numeric; r numeric; lb numeric; wide boolean; BEGIN
 IF least(tp,fp,fn,n)<0 OR tp+fn<>n THEN RAISE EXCEPTION 'invalid stratum counts'; END IF;
 p=tp::numeric/nullif(tp+fp,0);r=tp::numeric/nullif(n,0);lb=public.wilson_lb(tp,n);
 outcome=CASE WHEN zero_tolerance THEN CASE WHEN fp+fn>0 OR n=0 THEN 'FAIL' ELSE 'PASS' END
 WHEN n<min_n THEN CASE WHEN fp+fn=0 AND n>0 THEN 'UNDERPOWERED_OK' ELSE 'UNDERPOWERED_MISS' END
 WHEN coalesce(p,0)>=min_p AND coalesce(r,0)>=min_r THEN 'PASS' ELSE 'FAIL' END;
 wide=outcome='PASS' AND NOT zero_tolerance AND lb<.70;
 lev=CASE WHEN outcome IN ('FAIL','UNDERPOWERED_MISS') THEN 'human_classify' WHEN outcome='UNDERPOWERED_OK' OR wide THEN 'auto_with_flag' ELSE 'auto' END;
 RETURN jsonb_build_object('outcome',outcome,'n',n,'tp',tp,'fp',fp,'fn',fn,'precision',p,'recall',r,'recall_wilson_lb',lb,'flag',CASE WHEN wide THEN 'WIDE_CI' END,'automation_level',lev);
END $$;
DO $$ BEGIN IF to_regprocedure('public.r48_backtest_gate_base(uuid)') IS NULL THEN ALTER FUNCTION public.backtest_gate(uuid) RENAME TO r48_backtest_gate_base; END IF; END $$;
CREATE OR REPLACE FUNCTION public.backtest_gate(p_run_id uuid) RETURNS TABLE(metric text,pass boolean,actual text,required text)
LANGUAGE plpgsql AS $$ DECLARE cat text; d jsonb; vtp int; vfp int; vfn int; vn int; mn int; mp numeric; mr numeric; BEGIN
 ASSERT current_database() != 'yongxiang_plumb'; ASSERT current_database()='yongxiang_plumb_r39_clone';
 -- Preserve all independent safety, evidence and kappa gates and the legacy return signature.
 RETURN QUERY SELECT b.* FROM public.r48_backtest_gate_base(p_run_id) b WHERE b.metric !~ '^CAT-0[1-8]_PR$';
 IF p_run_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.switchboard_backtest_eval e WHERE e.run_id=p_run_id) OR EXISTS(SELECT 1 FROM public.r48_backtest_gate_base(p_run_id) b WHERE b.metric='BACKTEST-200' AND b.actual LIKE 'NOT_RUN%') THEN RETURN; END IF;
 FOR cat IN SELECT 'CAT-'||lpad(i::text,2,'0') FROM generate_series(1,10) i LOOP
 SELECT count(*) FILTER(WHERE e.predicted_category=cat AND g.gold_category=cat),
 count(*) FILTER(WHERE e.predicted_category=cat AND g.gold_category IS DISTINCT FROM cat),
 count(*) FILTER(WHERE e.predicted_category IS DISTINCT FROM cat AND g.gold_category=cat),count(*) FILTER(WHERE g.gold_category=cat)
 INTO vtp,vfp,vfn,vn FROM public.switchboard_backtest_eval e JOIN public.switchboard_gold_label g USING(sample_id) WHERE e.run_id=p_run_id;
 IF cat='CAT-10' THEN
  SELECT count(*) FILTER(WHERE g.gold_category=cat AND e.predicted_category=cat AND coalesce(e.predicted_is_otp,false)),
   count(*) FILTER(WHERE (e.predicted_category=cat AND g.gold_category IS DISTINCT FROM cat) OR (coalesce(e.predicted_is_otp,false) AND NOT g.gold_is_otp)),
   count(*) FILTER(WHERE g.gold_category=cat AND NOT coalesce(e.predicted_category=cat AND e.predicted_is_otp,false))
  INTO vtp,vfp,vfn FROM public.switchboard_backtest_eval e JOIN public.switchboard_gold_label g USING(sample_id) WHERE e.run_id=p_run_id;
 ELSIF cat='CAT-09' THEN
  SELECT count(*) FILTER(WHERE g.gold_category=cat AND coalesce(e.predicted_category=cat AND e.predicted_should_filter AND NOT e.predicted_emit_card,false)),
   count(*) FILTER(WHERE e.predicted_category=cat AND g.gold_category IS DISTINCT FROM cat),
   count(*) FILTER(WHERE g.gold_category=cat AND NOT coalesce(e.predicted_category=cat AND e.predicted_should_filter AND NOT e.predicted_emit_card,false))
  INTO vtp,vfp,vfn FROM public.switchboard_backtest_eval e JOIN public.switchboard_gold_label g USING(sample_id) WHERE e.run_id=p_run_id;
 END IF;
 SELECT c.min_n INTO mn FROM public.r48_config c;
 SELECT coalesce(t.min_precision,.90),coalesce(t.min_recall,.85) INTO mp,mr FROM (SELECT 1) x LEFT JOIN public.backtest_threshold t ON t.metric=cat AND t.stratum=cat;
 d=public.r48_stratum_result(vtp,vfp,vfn,vn,cat IN ('CAT-09','CAT-10'),mn,mp,mr);
 INSERT INTO public.category_automation(category,level,run_id) VALUES(cat,d->>'automation_level',p_run_id)
 ON CONFLICT(category) DO UPDATE SET level=excluded.level,run_id=excluded.run_id,set_at=now();
 metric=cat||'_PR';pass=d->>'outcome' IN ('PASS','UNDERPOWERED_OK');actual=d::text;required='count gate for n<10; otherwise P>=.90 R>=.85; safety zero tolerance';RETURN NEXT;
 END LOOP;
END $$;
INSERT INTO public.category_automation(category,level)
SELECT 'CAT-'||lpad(i::text,2,'0'),'human_classify' FROM generate_series(1,10) i ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.r48_route_category(p_category text) RETURNS jsonb LANGUAGE sql STABLE AS $$
 SELECT jsonb_build_object('automation_level',coalesce(a.level,'human_classify'),
 'role',CASE WHEN coalesce(a.level,'human_classify')='human_classify' THEN 'admin' ELSE 'case' END,
 'classification_pending',coalesce(a.level,'human_classify')='auto_with_flag')
 FROM (SELECT 1) x LEFT JOIN public.category_automation a ON a.category=p_category $$;
CREATE OR REPLACE FUNCTION public.r48_card_category_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE d jsonb;cat text;BEGIN
 cat=NEW.proposed_fields->>'category';
 IF cat IS NULL THEN RETURN NEW;END IF;
 d=public.r48_route_category(cat);
 NEW.proposed_fields=NEW.proposed_fields||d;
 IF d->>'automation_level'='human_classify' THEN
  NEW.kind='admin';NEW.role='admin';NEW.title='歸類：'||NEW.title;
  SELECT e.id INTO NEW.assignee_employee_id FROM public.employee e JOIN public.employee_role_map r ON r.employee_id=e.id AND r.role_code='admin' WHERE e.org_id=NEW.org_id AND e.identity_confirmed AND e.employment_status='active' ORDER BY e.id LIMIT 1;
  IF NEW.assignee_employee_id IS NULL THEN RAISE EXCEPTION 'no active administrative classifier';END IF;
  NEW.actions='[{"label":"完成歸類","action":"confirm"}]';
 ELSIF d->>'automation_level'='auto_with_flag' THEN
  NEW.title='⟨待確認⟩ '||NEW.title;
  NEW.proposed_fields=NEW.proposed_fields||'{"classification_label":"分類待確認","classification_wrong_label":"分類錯了"}'::jsonb;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS a_r48_card_category_guard ON public.card;
CREATE TRIGGER a_r48_card_category_guard BEFORE INSERT ON public.card FOR EACH ROW EXECUTE FUNCTION public.r48_card_category_guard();
CREATE TABLE IF NOT EXISTS public.shadow_draft_review(
 outbound_id uuid PRIMARY KEY REFERENCES public.outbound_message(id),used boolean NOT NULL,edited_fields jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(edited_fields)='array'),
 note text NOT NULL DEFAULT '',reviewed_by text NOT NULL CHECK(btrim(reviewed_by)<>''),reviewed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.day1_feedback(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id text NOT NULL DEFAULT 'YX' REFERENCES public.org(id),
 checkpoint text NOT NULL CHECK(checkpoint IN ('preopen','open','noon','close')),severity text NOT NULL CHECK(severity IN ('blocking','misclassification','experience')),
 reported_by text NOT NULL,first_impression text,blocked_step text,unclear_word text,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS public.r48_etl_operator(actor text PRIMARY KEY,can_pause boolean NOT NULL DEFAULT true);
INSERT INTO public.r48_etl_operator(actor) VALUES('A'),('JK') ON CONFLICT DO NOTHING;
REVOKE ALL ON public.r48_etl_operator FROM PUBLIC;
CREATE TABLE IF NOT EXISTS public.etl_pause_state(org_id text PRIMARY KEY REFERENCES public.org(id),paused boolean NOT NULL DEFAULT true,reason text NOT NULL DEFAULT 'Day-1 preopen checks pending',changed_by text NOT NULL DEFAULT 'A',changed_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.etl_pause_state(org_id) VALUES('YX') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS public.r48_etl_pause_log(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,org_id text NOT NULL,paused boolean NOT NULL,reason text NOT NULL,actor text NOT NULL,set_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION public.r48_set_etl_pause(p_org text,p_paused boolean,p_reason text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_actor text:=current_setting('app.actor',true);BEGIN
 ASSERT current_database() != 'yongxiang_plumb'; ASSERT current_database()='yongxiang_plumb_r39_clone';
 IF NOT EXISTS(SELECT 1 FROM public.r48_etl_operator o WHERE o.actor=v_actor AND o.can_pause) THEN RAISE EXCEPTION 'ETL pause restricted to A / JK'; END IF;
 IF coalesce(btrim(p_reason),'')='' THEN RAISE EXCEPTION 'reason required'; END IF;
 INSERT INTO public.etl_pause_state VALUES(p_org,p_paused,p_reason,v_actor,now()) ON CONFLICT(org_id) DO UPDATE SET paused=excluded.paused,reason=excluded.reason,changed_by=excluded.changed_by,changed_at=now();
 INSERT INTO public.r48_etl_pause_log(org_id,paused,reason,actor) VALUES(p_org,p_paused,p_reason,v_actor);
END $$;
CREATE OR REPLACE FUNCTION public.r48_etl_may_ingest(p_org text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT NOT coalesce((SELECT paused FROM public.etl_pause_state WHERE org_id=p_org),true) $$;
CREATE OR REPLACE FUNCTION public.r48_email_etl_pause_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE org text;BEGIN
 org=coalesce(NEW.org_id,(SELECT m.org_id FROM public.email_mailbox m WHERE m.id=NEW.mailbox_id),'YX');
 IF NOT public.r48_etl_may_ingest(org) THEN RAISE EXCEPTION 'ETL paused for %; retain IMAP cursor and retry after resume',org USING ERRCODE='55000';END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS a00_r48_email_etl_pause ON public.email_message;
CREATE TRIGGER a00_r48_email_etl_pause BEFORE INSERT ON public.email_message FOR EACH ROW EXECUTE FUNCTION public.r48_email_etl_pause_guard();
CREATE OR REPLACE VIEW public.r48_day1_health_v AS
SELECT e.org_id,e.paused,e.reason,
 CASE WHEN e.paused THEN '暫停收件，原因：'||e.reason ELSE 'YX 試運轉 第 1 天' END banner,
 (SELECT count(*) FROM public.card c WHERE c.org_id=e.org_id AND c.created_at::date=current_date) today_cards,
 (SELECT count(*) FROM public.day1_feedback f WHERE f.org_id=e.org_id AND f.created_at::date=current_date) today_feedback,
 (SELECT count(*) FROM public.shadow_draft_review r WHERE r.reviewed_at::date=current_date) today_draft_reviews
FROM public.etl_pause_state e;
-- Preserve terminal states in the inherited Shadow guard; mode stays dry_run.
CREATE OR REPLACE FUNCTION r47.card_dry_run() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,r47 AS $$
BEGIN
 IF NEW.org_id='YX' AND NEW.status='open' AND NOT coalesce((public.org_live_ready('YX')->>'ready')::bool,false) THEN
  NEW.mode='dry_run';
  IF NEW.state NOT IN ('superseded','superseded_by_live') THEN NEW.state='dry_run';END IF;
 END IF;RETURN NEW;
END $$;
-- Supersede obsolete unresolved cards after a controlled identity-mode rebind.
UPDATE public.card c SET state='superseded' WHERE c.idempotency_key LIKE 'r48:quote-choose:%' AND c.status='open'
 AND c.state NOT IN ('superseded','superseded_by_live') AND NOT EXISTS(SELECT 1 FROM public.case_quote_summary_v s WHERE s.case_id=c.case_id AND s.needs_human AND s.duplicate_cohort);
-- Durable choose cards, one per unresolved case, in the case inbox.
INSERT INTO public.card(org_id,case_id,assignee_employee_id,kind,idempotency_key,title,proposed_fields,actions,role,mode)
SELECT 'YX',s.case_id,(SELECT e.id FROM public.employee e WHERE e.org_id='YX' AND e.identity_confirmed AND e.employment_status='active' AND e.full_name LIKE '%柏頤%' ORDER BY e.id LIMIT 1),
 'confirm','r48:quote-choose:'||s.case_id,'待業務確認',jsonb_build_object('workspace','永祥 · 業主往來','case_code',s.case_code,'quotes',s.quotes),
 '[{"label":"選擇報價列","action":"confirm"}]','case','dry_run'
FROM public.case_quote_summary_v s WHERE s.needs_human AND s.duplicate_cohort ON CONFLICT(idempotency_key) DO NOTHING;
CREATE OR REPLACE FUNCTION public.r48_assert_all() RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE n int; rows_n int; src_n int; pending int; cards int; full_n int; full_rows int; BEGIN
 ASSERT current_database() != 'yongxiang_plumb'; ASSERT current_database()='yongxiang_plumb_r39_clone';
 SELECT count(*),sum(quote_rows),count(*) FILTER(WHERE needs_human) INTO n,rows_n,pending FROM public.case_quote_summary_v WHERE duplicate_cohort AND no_v4;
 SELECT count(*) INTO src_n FROM public.r48_quote_source WHERE record ? 'cohort_group';
 SELECT count(*),sum(quote_rows) INTO full_n,full_rows FROM public.case_quote_summary_v WHERE duplicate_cohort AND no_v4;
 IF n<>36 OR rows_n<>src_n THEN RAISE EXCEPTION 'QC-01 source reconciliation failed: %, %, %',n,rows_n,src_n;END IF;
 IF EXISTS(SELECT 1 FROM public.quote_case_link GROUP BY case_id HAVING count(*) FILTER(WHERE link_role='canonical')>1) THEN RAISE EXCEPTION 'QC-02 multiple canonical';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.case_quote_summary_v WHERE case_code='C115211-01A' AND duplicate_cohort) THEN RAISE EXCEPTION 'QC-03 absent example';END IF;
 IF EXISTS(SELECT 1 FROM public.case_quote_summary_v WHERE needs_human AND (canonical_quote_no IS NOT NULL OR canonical_amount IS NOT NULL)) THEN RAISE EXCEPTION 'QC-04 unresolved amount leaked';END IF;
 SELECT count(*) INTO cards FROM public.card WHERE idempotency_key LIKE 'r48:quote-choose:%' AND state NOT IN ('superseded','superseded_by_live');
 IF cards<pending THEN RAISE EXCEPTION 'QC-04 missing choose cards';END IF;
 IF EXISTS(SELECT 1 FROM public.r48_quote_original o LEFT JOIN public.quote q USING(id) WHERE q.id IS NULL) OR (SELECT count(*) FROM public.r48_quote_source s JOIN public.quote q ON q.lark_record_id=s.record_id)<>423 THEN RAISE EXCEPTION 'QC-05 missing original quote';END IF;
 IF public.wilson_lb(4,4)<>.5101 OR public.wilson_lb(0,0) IS NOT NULL THEN RAISE EXCEPTION 'Wilson failed';END IF;
 IF public.r48_stratum_result(4,0,0,4)->>'outcome'<>'UNDERPOWERED_OK'
 OR public.r48_stratum_result(3,0,1,4)->>'outcome'<>'UNDERPOWERED_MISS'
 OR public.r48_stratum_result(4,0,0,4,true)->>'outcome'<>'PASS'
 OR public.r48_stratum_result(2,0,1,3,true)->>'outcome'<>'FAIL'
 OR public.r48_stratum_result(9,0,1,10)->>'flag'<>'WIDE_CI'
 THEN RAISE EXCEPTION 'small stratum behavior failed';END IF;
 IF (SELECT count(*) FROM public.category_automation WHERE category ~ '^CAT-(0[1-9]|10)$')<>10 THEN RAISE EXCEPTION 'missing category automation levels';END IF;
 IF to_regclass('public.category_automation') IS NULL OR to_regclass('public.shadow_draft_review') IS NULL THEN RAISE EXCEPTION 'missing runbook tables';END IF;
 RETURN jsonb_build_object('QC-01',CASE WHEN rows_n=75 AND full_n=36 AND full_rows=75 THEN 'PASS' ELSE format('SOURCE_MISMATCH: cohort expected 36/75 actual %s/%s; all no_v4=%s/%s',n,rows_n,full_n,full_rows) END,'QC-02','PASS:SQL invariant; Python cross-diff required','QC-03','PASS:identity; Python search required','QC-04','PASS','QC-05','PASS','wilson_lb','PASS','category_automation','PASS','shadow_draft_review','PASS');
END $$;
DO $$ BEGIN IF to_regprocedure('public.r48_r32_assert_all_base()') IS NULL THEN ALTER FUNCTION public.r32_assert_all() RENAME TO r48_r32_assert_all_base; END IF;END $$;
-- Later migrations may have wrapped this function. Their chain already calls
-- R48's original wrapper by OID; preserve that chain during an R48 replay.
DO $integrate$
BEGIN
 IF to_regprocedure('public.r50_r32_assert_all_chain()') IS NULL THEN
  EXECUTE $ddl$CREATE OR REPLACE FUNCTION public.r32_assert_all() RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE r jsonb;BEGIN r=public.r48_assert_all();
 IF r->>'QC-01'<>'PASS' THEN RAISE EXCEPTION 'R48 cutover blocked: %',r->>'QC-01';END IF;
 RETURN public.r48_r32_assert_all_base()||r;END $$;$ddl$;
 END IF;
END $integrate$;

COMMIT;
